#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n,m;unsigned long long k;cin>>n>>m>>k;int length=n+m-1;vector<int>priority(length,INT_MAX),value(length,-1);for(int i=0;i<n;i++)for(int j=0,p;j<m;j++){cin>>p;priority[i+j]=min(priority[i+j],p);}vector<int>order(length);iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return priority[a]<priority[b];});const unsigned long long cap=1000000000000000001ULL;auto count=[&](){vector<unsigned long long>dp(length+1),next(length+1);dp[0]=1;for(int pos=0;pos<length;pos++){fill(next.begin(),next.end(),0);for(int balance=0;balance<=length;balance++)if(dp[balance])for(int ch=0;ch<2;ch++)if(value[pos]<0||value[pos]==ch){int nb=balance+(ch? -1:1);if(nb<0||nb>length-pos-1)continue;next[nb]=min(cap,next[nb]+dp[balance]);}dp.swap(next);}return dp[0];};for(int p:order){value[p]=0;auto ways=count();if(ways<k){value[p]=1;k-=ways;}}for(int i=0;i<n;i++){for(int j=0;j<m;j++)cout<<(value[i+j]?')':'(');cout<<'\n';}}
